import React, { useState, useEffect } from 'react';
import styles from './styles/style';
import { View, Text, Image, SafeAreaView, StyleSheet, TouchableOpacity, Alert, TextInput, ScrollView } from 'react-native';
import LinearGradient from 'react-native-linear-gradient';

interface ItemAddProps {
  username: string;
  avatar: string;
  onLogout: () => void;
  onNavigateToList: () => void;
}

const wearLevels = ["Factory New", "Minimal Wear", "Field-Tested", "Well-Worn", "Battle-Scarred"];

const rarityStyleMap = {
  'exotic':    { colors: ['rgba(142,0,225,0.1)', 'transparent'], borderColor: '#8d00e1' },
  'classified':{ colors: ['rgba(142,0,225,0.1)', 'transparent'], borderColor: '#8d00e1' },
  'superior':  { colors: ['rgba(142,0,225,0.1)', 'transparent'], borderColor: '#8d00e1' },

  'covert':        { colors: ['rgba(194,0,0,0.05)', 'transparent'], borderColor: '#c20000' },
  'master':        { colors: ['rgba(194,0,0,0.05)', 'transparent'], borderColor: '#c20000' },
  'extraordinary': { colors: ['rgba(194,0,0,0.05)', 'transparent'], borderColor: '#c20000' },

  'restricted':   { colors: ['rgba(84,41,136,0.1)', 'transparent'], borderColor: '#532988' },
  'exceptional':  { colors: ['rgba(84,41,136,0.1)', 'transparent'], borderColor: '#532988' },
  'remarkable':   { colors: ['rgba(84,41,136,0.1)', 'transparent'], borderColor: '#532988' },

  'industrial grade': { colors: ['rgba(81,138,251,0.1)', 'transparent'], borderColor: '#5189fb' },

  'contraband':   { colors: ['rgba(217,172,70,0.1)', 'transparent'], borderColor: '#d9ac46' },

  'base grade':      { colors: ['rgba(142,180,255,0.1)', 'transparent'], borderColor: '#8eb3ff' },
  'consumer grade':  { colors: ['rgba(142,180,255,0.1)', 'transparent'], borderColor: '#8eb3ff' },

  'distinguished':   { colors: ['rgba(41,71,157,0.1)', 'transparent'], borderColor: '#29479d' },
  'high grade':      { colors: ['rgba(41,71,157,0.1)', 'transparent'], borderColor: '#29479d' },
  'mil-spec grade':  { colors: ['rgba(41,71,157,0.1)', 'transparent'], borderColor: '#29479d' },
};

const ItemAdd: React.FC<ItemAddProps> = ({ username, avatar, onLogout, onNavigateToList }) => {
  let [isMenuOpen, setIsMenuOpen] = useState(false);
  let [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  let [itemName, setItemName] = useState('');
  let [selectedType, setSelectedType] = useState('');
  let [condition, setCondition] = useState('');
  let [isFilterVisible, setIsFilterVisible] = useState(false);
  let [suggestions, setSuggestions] = useState<any[]>([]); // Przechowuje sugestie
  let [images, setImages] = useState<{ [key: string]: string }>({}); // Przechowuje imageurl dla fullname
  let [showSuggestions, setShowSuggestions] = useState(false); // Kontroluje widoczność sugestii
  const [activeMenu2, setActiveMenu2] = useState<number | null>(null);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleUserMenu = () => {
    setIsUserMenuOpen(!isUserMenuOpen);
  };

  const handleLogout = () => {
    Alert.alert(
      'Wylogowanie',
      'Czy na pewno chcesz się wylogować?',
      [
        { text: 'Anuluj', style: 'cancel' },
        { text: 'Wyloguj', onPress: onLogout },
      ],
      { cancelable: true }
    );
  };

  const handleSearch = async () => {
    setShowSuggestions(false);
    setImages({});
    
    // Buduj URL z parametrami zapytania
    const isStatTrak = selectedType === 'StatTrak™';
    const isSouvenir = selectedType === 'Souvenir';
    const queryParams = new URLSearchParams({
      query: itemName
    });
    
    // Dodaj warunki tylko jeśli są wybrane
    if (condition) {
      queryParams.append('condition', condition);
    }
    if (isStatTrak) {
      queryParams.append('stattrak', 'true');
    }
    if (isSouvenir) {
      queryParams.append('souvenir', 'true');
    }
    
    // Wykonaj zapytanie
    fetch(`http://192.168.55.10:8000/suggestions?${queryParams.toString()}`)
      .then((response) => response.json())
      .then((data) => {
        const newSuggestions: any[] = [];
        const newImages: { [key: string]: string } = {};

        // Przetwarzanie otrzymanych danych
        for (const suggestion of data) {
          if (suggestion.imageurl) {
            newSuggestions.push(suggestion);
            newImages[suggestion.display_fullname] = suggestion.imageurl;
          }
        }

        setSuggestions(newSuggestions);
        setImages(newImages);
        setShowSuggestions(true);
      })
      .catch((error) => {
        console.error('Błąd podczas pobierania sugestii:', error);
      });
  };

  const toggleFilterVisibility = () => {
    setIsFilterVisible(!isFilterVisible);
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.menu}>
        <TouchableOpacity onPress={toggleMenu}>
          <Image
            source={require('./assets/menu.png')}
            style={styles.menuIcon}
          />
        </TouchableOpacity>
        <Image
          source={require('./assets/skinradar.png')}
          style={styles.logo}
        />
        <TouchableOpacity onPress={toggleUserMenu}>
          <Image
            source={{ uri: avatar }}
            style={styles.avatar}
          />
        </TouchableOpacity>
      </View>
      <ScrollView contentContainerStyle={styles.scrollContainer} showsVerticalScrollIndicator={false}>
        {isMenuOpen && (
          <View style={styles.dropdownMenu}>
            <TouchableOpacity style={styles.dropdownButton} onPress={onNavigateToList}>
              <Text style={styles.dropdownButtonText}>LISTA</Text>
            </TouchableOpacity>
            <TouchableOpacity style={styles.dropdownButton}>
              <Text style={styles.dropdownButtonText}>DODAJ</Text>
            </TouchableOpacity>
          </View>
        )}

        {isUserMenuOpen && (
          <View style={styles.userMenu}>
            <Text style={styles.userMenuText}>{username}</Text>
            <TouchableOpacity style={styles.logoutButton} onPress={handleLogout}>
              <Image
                source={require('./assets/logout.png')}
                style={styles.logoutIcon}
              />
            </TouchableOpacity>
          </View>
        )}

        <View style={styles.searchContainer}>
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 10 }}>
            <View style={[styles.input, { flexDirection: 'row', alignItems: 'center', flex: 1, paddingLeft: 10, paddingRight: 0 }]}>
              <Image
                source={require('./assets/searchimage.png')}
                style={styles.searchIcon}
              />
              <TextInput
                style={[styles.inputInner, { flex: 1 }]}
                placeholder="Wpisz nazwę przedmiotu"
                placeholderTextColor="#7C8BA1"
                value={itemName}
                onChangeText={setItemName}
              />
            </View>
            <TouchableOpacity onPress={toggleFilterVisibility} style={{ marginLeft: 10 }}>
              <Image
                source={require('./assets/filter.png')}
                style={styles.filterIcon}
              />
            </TouchableOpacity>
          </View>
          {isFilterVisible && (
            <View style={styles.filterContainer}>
              <View style={styles.checkboxContainer}>
                <TouchableOpacity
                  onPress={() => setSelectedType(selectedType === 'StatTrak™' ? '' : 'StatTrak™')}
                  style={[styles.checkboxButton, selectedType === 'StatTrak™' && styles.checkboxButtonActive]}
                >
                  <Text style={styles.checkboxText}>StatTrak™</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  onPress={() => setSelectedType(selectedType === 'Souvenir' ? '' : 'Souvenir')}
                  style={[styles.checkboxButton, selectedType === 'Souvenir' && styles.checkboxButtonActive]}
                >
                  <Text style={styles.checkboxText}>Souvenir</Text>
                </TouchableOpacity>
              </View>
              <View style={styles.checkboxContainer}>
                {wearLevels.map((option) => (
                  <TouchableOpacity
                    key={option}
                    onPress={() => setCondition(condition === option ? '' : option)}
                    style={[styles.checkboxButton, condition === option && styles.checkboxButtonActive]}
                  >
                    <Text style={styles.checkboxText}>{option}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          )}
          <TouchableOpacity style={styles.searchButton} onPress={handleSearch}>
            <Text style={styles.searchButtonText}>Wyszukaj</Text>
          </TouchableOpacity>
        </View>

        {showSuggestions && (
          <View style={styles.suggestionsContainer}>
            {suggestions.map((suggestion, index) => {
              const rarityKey = suggestion.rarity?.toLowerCase().trim() as keyof typeof rarityStyleMap | undefined;
              const rarityStyle = rarityKey ? rarityStyleMap[rarityKey] : undefined;

              if (rarityStyle) {
                return (
                  <LinearGradient
                    key={index}
                    colors={rarityStyle.colors}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 0 }}
                    style={[
                      styles.suggestionItem,
                      { borderLeftWidth: 2, borderLeftColor: rarityStyle.borderColor }
                    ]}
                  >
                    {(() => {
                      // Użyj display_fullname lub market_hash_name
                      const name = suggestion.display_fullname ?? suggestion.market_hash_name;
                      if (name.startsWith('StatTrak™ ')) {
                        return <Text style={styles.suggestionPrefix}>StatTrak™</Text>;
                      }
                      if (name.startsWith('Souvenir ')) {
                        return <Text style={styles.suggestionPrefix}>Souvenir</Text>;
                      }
                      if (name.startsWith('★ StatTrak™ ')) {
                        return <Text style={styles.suggestionPrefix}>StatTrak™</Text>;
                      }
                      return null;
                    })()}

                    <Text style={styles.suggestionText}>
                      {/* Nazwa bez prefixu i bez wear */}
                      {(suggestion.display_fullname ?? suggestion.market_hash_name)
                        .replace(/^StatTrak™ /, '')
                        .replace(/^Souvenir /, '')
                        .replace(/^★ StatTrak™ /, '★ ')
                        .replace(/\s*\((Factory New|Minimal Wear|Field-Tested|Well-Worn|Battle-Scarred)\)$/, '')
                      }
                    </Text>
                    {suggestion.display_wear && (
                      <Text style={styles.suggestionWear}>{suggestion.display_wear}</Text>
                    )}
                    <Text style={styles.suggestionDetails}>
                      Rarity: {suggestion.rarity}, Description: {suggestion.description}, Need Wear: {suggestion.need_wear}
                    </Text>
                    {suggestion.imageurl && (
                      <Image
                        source={{ uri: suggestion.imageurl }}
                        style={styles.suggestionImage}
                      />
                    )}
                  </LinearGradient>
                );
              } else {
                // domyślny styl jeśli brak rarity
                return (
                  <View key={index} style={styles.suggestionItem}>
                    {(() => {
                      // Użyj display_fullname lub market_hash_name
                      const name = suggestion.display_fullname ?? suggestion.market_hash_name;
                      if (name.startsWith('StatTrak™ ')) {
                        return <Text style={styles.suggestionPrefix}>StatTrak™</Text>;
                      }
                      if (name.startsWith('Souvenir ')) {
                        return <Text style={styles.suggestionPrefix}>Souvenir</Text>;
                      }
                      if (name.startsWith('★ StatTrak™ ')) {
                        return <Text style={styles.suggestionPrefix}>StatTrak™</Text>;
                      }
                      return null;
                    })()}

                    <Text style={styles.suggestionText}>
                      {/* Nazwa bez prefixu i bez wear */}
                      {(suggestion.display_fullname ?? suggestion.market_hash_name)
                        .replace(/^StatTrak™ /, '')
                        .replace(/^Souvenir /, '')
                        .replace(/^★ StatTrak™ /, '★ ')
                        .replace(/\s*\((Factory New|Minimal Wear|Field-Tested|Well-Worn|Battle-Scarred)\)$/, '')
                      }
                    </Text>
                    {suggestion.display_wear && (
                      <Text style={styles.suggestionWear}>{suggestion.display_wear}</Text>
                    )}
                    <Text style={styles.suggestionDetails}>
                      Rarity: {suggestion.rarity}, Description: {suggestion.description}, Need Wear: {suggestion.need_wear}
                    </Text>
                    {suggestion.imageurl && (
                      <Image
                        source={{ uri: suggestion.imageurl }}
                        style={styles.suggestionImage}
                      />
                    )}
                  </View>
                );
              }
            })}
          </View>
        )}

      </ScrollView>

      <View style={styles.menu2}>
        {[
          require('./assets/settings.png'),
          require('./assets/bell.png'),
          require('./assets/questmark.png'),
        ].map((icon, idx) => (
          <TouchableOpacity
            key={idx}
            onPress={() => setActiveMenu2(idx)}
            style={styles.menu2Button}
            activeOpacity={0.7}
          >
            <View style={[
              styles.menu2IconWrapper,
              activeMenu2 === idx && styles.menu2IconWrapperActive
            ]}>
              <Image
                source={icon}
                style={[
                  styles.menuButtonIcon,
                  activeMenu2 === idx && styles.menuButtonIconActive,
                ]}
              />
            </View>
          </TouchableOpacity>
        ))}
      </View>
    </SafeAreaView>
  );
};

export default ItemAdd;
